// generated by `pocket gen` from engine/*/meta/*.toml; do not edit

export interface Vec2 { x: number; y: number }
export interface Vec3 { x: number; y: number; z: number }
export interface Vec4 { x: number; y: number; z: number; w: number }
export interface Quat { x: number; y: number; z: number; w: number }
export interface Color { r: number; g: number; b: number; a: number }

/** One morph target weight set by script (docs/design/animation.md, Morph targets): the target by name or index, and the weight that replaces the clip's for it. */
export interface MorphWeight {
    /** Target name from the asset (animation.clips lists them), or its index as a string. */
    target: string;
    /** 0 leaves the vertices where the mesh has them, 1 moves them fully to the target. */
    weight: number;
}

/** One clip layered over an Animator's base clip (docs/design/animation.md): sampled at its own time, limited to the nodes of `mask`, and either blended in at `weight` or added as the clip's change since its first frame. animation.layer adds, updates and removes layers. */
export interface AnimationLayer {
    /** Clip name from the asset (animation.clips lists them). */
    clip: string;
    /** 0..1: how much of the layer shows (the blend factor, or the scale of an additive change). */
    weight: number;
    /** Node names, comma separated, whose subtrees the layer may move; empty means every node the clip animates. */
    mask: string;
    /** Add the clip's change since its first frame onto the pose so far instead of blending toward the clip. */
    additive: boolean;
    /** Whether the layer's time advances; animation.stop clears it with the base clip's. */
    playing: boolean;
    /** Wrap at the end (else stop on the last frame and emit animation.finished with the layer index). */
    loop: boolean;
    /** Playback rate multiplier. */
    speed: number;
    /** Seconds into the clip; advanced by the engine, writable to seek. */
    time: number;
}

/** Position, rotation and scale relative to the parent entity (or the world when there is no parent). */
export interface Transform {
    /** Local position in meters. */
    position: Vec3;
    /** Local rotation as a unit quaternion (x, y, z, w). */
    rotation: Quat;
    /** Local scale. */
    scale: Vec3;
}

/** World-space transform computed from the Transform hierarchy every tick. Read only. */
export interface WorldTransform {
    /** World position. */
    position: Vec3;
    /** World rotation. */
    rotation: Quat;
    /** World scale. */
    scale: Vec3;
}

/** Linear and angular velocity. The built-in motion system integrates Transform from it every tick. */
export interface Velocity {
    /** Meters per second, in the parent's space. */
    linear: Vec3;
    /** Radians per second around local X, Y, Z. */
    angular: Vec3;
}

/** Hit points. Gameplay decides what zero means; the engine only stores and reports it. */
export interface Health {
    /** Current hit points. */
    current: number;
    /** Maximum hit points. */
    max: number;
}

/** Seconds remaining before the entity is destroyed by the lifetime system. */
export interface Lifetime {
    /** Remaining seconds; the entity is destroyed when it reaches zero. */
    seconds: number;
}

/** The renderer uses the first active camera. Perspective by default; orthographic for 2D (looking down -Z with +Y up is the 2D convention). */
export interface Camera {
    /** Vertical field of view in degrees (perspective). */
    fov_degrees: number;
    /** Parallel projection: no perspective, sizes do not shrink with distance. */
    orthographic: boolean;
    /** Half of the visible height in world units when orthographic. */
    ortho_size: number;
    /** Near clip distance. */
    near: number;
    /** Far clip distance. */
    far: number;
    /** Whether this camera renders. */
    active: boolean;
}

/** A light source. kind 0 = directional (shines along -Z of the entity), 1 = point. */
export interface Light {
    /** 0 directional, 1 point. */
    kind: number;
    /** Linear RGB color; alpha unused. */
    color: Color;
    /** Multiplier applied to color. */
    intensity: number;
    /** Point light range in meters. */
    range: number;
}

/** Draws a mesh: a built-in primitive or a glTF file from the project's assets, tinted by a color and optionally textured. */
export interface MeshRenderer {
    /** cube, sphere, plane, cylinder, quad (unit square in XY facing +Z), or a project-relative glTF path such as assets/crate.glb (all of its nodes, with their own materials). */
    mesh: string;
    /** Base color, linear RGB; multiplies the asset's material color. */
    color: Color;
    /** Project-relative image (png, jpg) multiplied into the color; overrides the asset's base color texture. Empty for none. */
    texture: string;
    /** 0 dielectric to 1 metal; negative keeps the asset material's value (0 for primitives). */
    metallic: number;
    /** 0 mirror to 1 matte; negative keeps the asset material's value (1 for primitives). */
    roughness: number;
    /** Light the surface gives off regardless of lighting, added to the asset material's emissive color. */
    emissive: Color;
    /** Project-relative tangent-space normal map (+Y up); overrides the asset's. Empty for none. */
    normal_map: string;
    /** Whether the mesh is drawn. */
    visible: boolean;
}

/** A 2D image: a textured unit square in the entity's XY plane, sized in world units, unlit, alpha blended, drawn after meshes in layer order. Use with an orthographic camera looking down -Z. */
export interface Sprite {
    /** Project-relative image (png, jpg). Empty draws a solid color. */
    texture: string;
    /** Width and height in world units. */
    size: Vec2;
    /** Tint and opacity, multiplied into the texture. */
    color: Color;
    /** Point of the image at the entity's origin: (0,0) bottom-left, (0.5,0.5) center, (1,1) top-right. */
    anchor: Vec2;
    /** Draw order among sprites; higher is drawn later (on top). */
    layer: number;
    /** Sub-rectangle of the texture as u0, v0, u1, v1 (0..1, v down), for sprite sheets. */
    uv: Vec4;
    /** Mirror horizontally. */
    flip_x: boolean;
    /** Mirror vertically. */
    flip_y: boolean;
    /** Texture sampling: linear (smooth) or nearest (crisp pixels, no bleeding between sheet tiles). */
    filter: string;
    /** Whether the sprite is drawn. */
    visible: boolean;
}

/** Plays a clip (a run of sheet frames registered with sprite.clip or [sprite_clips] in project.toml) on the entity's Sprite: every tick the engine advances time, picks the frame and writes Sprite.uv (and texture when the clip names one). Emits sprite.finished when a non-looping clip ends. */
export interface SpriteAnimation {
    /** Clip name; empty plays nothing. */
    clip: string;
    /** Whether time advances. */
    playing: boolean;
    /** Wrap at the end (else stop on the last frame and emit sprite.finished); sprite.play takes it from the clip unless told otherwise. */
    loop: boolean;
    /** Playback rate multiplier; negative plays backwards. */
    speed: number;
    /** Frames per second; 0 uses the clip's rate. */
    fps: number;
    /** Index into the clip's frame list (read to know where it is, write to jump). */
    frame: number;
    /** Seconds into the current frame; advanced by the engine. */
    time: number;
    /** Set when a non-looping clip reached its end; cleared by play. */
    finished: boolean;
}

/** Draws a Tiled map (a .tmj file in the project) with the entity at the map's top-left corner: tile (x, y) occupies world x from x*tile_size to (x+1)*tile_size and y from -(y+1)*tile_size to -y*tile_size, so rows go down as in Tiled. Every visible tile layer is one static mesh drawn unlit through the sprite path (docs/design/tilemaps.md); tilemap.* commands answer what is where, tilemap.set / tilemap.fill edit the map for every entity drawing it and tilemap.save writes it back. */
export interface TileMap {
    /** Project-relative Tiled JSON map (.tmj). */
    map: string;
    /** Draw only this tile layer; empty draws every visible one. */
    layer: string;
    /** World units per tile. */
    tile_size: number;
    /** Tint and opacity over the whole map. */
    color: Color;
    /** Draw order among sprites (Sprite.layer); layers of the map draw in file order on top of this. */
    order: number;
    /** Whether the map is drawn. */
    visible: boolean;
}

/** Plays a glTF animation clip of the entity's MeshRenderer asset: every tick the engine advances time, samples the clip's keyframes into the file's node hierarchy and poses the skinned mesh (docs/design/animation.md). Emits animation.finished when a non-looping clip ends. Use animation.play / animation.stop, or set the fields directly. */
export interface Animator {
    /** Clip name from the asset (animation.clips lists them); empty plays nothing (bind pose). */
    clip: string;
    /** Whether time advances. */
    playing: boolean;
    /** Wrap at the end (else stop on the last frame and emit animation.finished). */
    loop: boolean;
    /** Playback rate multiplier. */
    speed: number;
    /** Seconds into the clip; advanced by the engine, writable to seek. */
    time: number;
    /** Set when a non-looping clip reached its end; cleared by play. */
    finished: boolean;
    /** Seconds of cross-fade from from_clip into clip; animation.play {fade} sets it. 0 when no fade is running. */
    fade: number;
    /** Seconds into the cross-fade, advanced by the engine; the blend weight is fade_time / fade, smoothed. */
    fade_time: number;
    /** The clip fading out (keeps playing at its own time until the fade ends); empty when none. */
    from_clip: string;
    /** Seconds into from_clip, advanced by the engine. */
    from_time: number;
    /** Clips layered over the base clip, applied in order after any cross-fade (animation.layer manages them). */
    layers: AnimationLayer[];
    /** 0 off; 1 the root node's translation is pinned to the clip's first frame and its change moves the entity's Transform, so a walk cycle carries the character; 2 pins the root and only reports root_delta for the script to apply (docs/design/animation.md, Root motion). */
    root_motion: number;
    /** The node whose translation is the root motion; empty picks the clip's topmost node with a translation track. */
    root: string;
    /** The root's translation change this tick while root_motion is on, in the asset's space, or relative to the root's heading when root_rotation is on (written by the engine). */
    root_delta: Vec3;
    /** With root_motion on, the root's yaw (its rotation about the asset's +Y) is root motion too: pinned to the clip's first frame in the pose, its change turns the entity (mode 1) or is reported in root_delta_yaw (mode 2), and root_delta is taken relative to the root's heading so a turning walk follows its arc (docs/design/animation.md, Root motion). */
    root_rotation: boolean;
    /** The root's yaw change this tick in radians while root_rotation is on (written by the engine). */
    root_delta_yaw: number;
}

/** Inverse kinematics on a chain of the entity's skinned mesh: after the clips and layers pose the skeleton, the `bones` joints that end at node `end` bend so that the effector (`tip` in the end node's space) reaches `target` (world space) or the position of `target_entity`, solved by FABRIK with an optional pole (docs/design/animation.md, Inverse kinematics). Works without an Animator too (over the rest pose). Writes error and reached each tick; animation.pose reports the effector. */
export interface IK {
    /** The chain's last node, a joint name (animation.clips lists the skins' joints). */
    end: string;
    /** How many bones the chain has, counted up from `end` (2 for a limb: upper and lower). */
    bones: number;
    /** The effector in the end node's space: the far end of the last bone, e.g. [0, 1, 0] for a unit bone along +Y. */
    tip: Vec3;
    /** Where the effector should be, in world space (used when target_entity is empty). */
    target: Vec3;
    /** An entity (name or path) whose world position is the target; empty uses target. */
    target_entity: string;
    /** An entity the chain's middle joints bend toward, the knee or elbow hint; empty keeps the bend the pose has. */
    pole_entity: string;
    /** The most any joint of the chain may bend, in degrees: the angle between its bone and the bone above it (for the chain's first joint, its parent's bone, or the direction the pose gives the first bone when it has no parent). 180 leaves the bend free; a target the limited chain cannot reach leaves error and reached false. */
    max_bend: number;
    /** How much of the solve applies: 0 the posed chain, 1 the solved one. */
    weight: number;
    /** FABRIK passes per tick (each is a backward and a forward sweep). */
    iterations: number;
    /** The solve stops once the effector is this close to the target, in meters. */
    tolerance: number;
    /** Distance from the effector to the target after the solve, in meters (written by the engine). */
    error: number;
    /** Whether the effector ended within tolerance (written by the engine). */
    reached: boolean;
    /** The largest bend among the chain's joints after the solve, in degrees (written by the engine). */
    bend: number;
}

/** Aims one node of the entity's skinned mesh at a point after the clips, layers and IK pose it: the node turns so that its `forward` axis points at `target` (world space) or at `target_entity`, at most `max_angle` degrees away from the posed direction, scaled by `weight` (docs/design/animation.md, Look-at). Writes angle each tick. */
export interface LookAt {
    /** The node that turns: a joint, or any node of the asset. */
    node: string;
    /** The node's aiming axis in its own space. */
    forward: Vec3;
    /** The point to aim at, in world space (used when target_entity is empty). */
    target: Vec3;
    /** An entity (name or path) whose world position is the target; empty uses target. */
    target_entity: string;
    /** How much of the turn applies: 0 none, 1 the full aim. */
    weight: number;
    /** The most the node may turn away from its posed direction, in degrees. */
    max_angle: number;
    /** How fast the aim may turn, in degrees per second: each tick the aim moves toward the target by at most this much, from where the pose points on the first tick, so a head follows smoothly; 0 aims at once. */
    speed: number;
    /** The turn applied this tick in degrees, after the limit and the weight (written by the engine). */
    angle: number;
    /** The direction the node aims along, in the entity's space, before max_angle and weight (written by the engine; zero until the first tick). */
    aim: Vec3;
}

/** Spawns particles at the entity: small unlit quads (camera-facing billboards, or XY sprites) with a life, a velocity from a cone, gravity, drag, and size and color fading from start to end. Simulated by the engine on the fixed tick with a random stream seeded from the entity, so runs are deterministic. particles.burst emits a batch at once. */
export interface ParticleEmitter {
    /** Project-relative image; empty draws soft solid quads. */
    texture: string;
    /** Whether particles spawn continuously at rate. */
    emitting: boolean;
    /** Particles per second while emitting. */
    rate: number;
    /** Most particles alive at once from this emitter (older ones are not replaced; spawning waits). */
    max: number;
    /** Seconds a particle lives: min and max, drawn uniformly. */
    lifetime: Vec2;
    /** Initial speed: min and max. */
    speed: Vec2;
    /** Center of the emission cone, in the emitter's local frame. */
    direction: Vec3;
    /** Half-angle of the cone in degrees (0 is a beam, 180 is every direction). */
    spread: number;
    /** Acceleration applied to every particle, world units per second squared. */
    gravity: Vec3;
    /** Fraction of velocity lost per second. */
    drag: number;
    /** Quad size in world units at birth and at death. */
    size: Vec2;
    /** Tint at birth. */
    color: Color;
    /** Tint at death; alpha 0 fades out. */
    color_end: Color;
    /** Draw order among sprites and particles. */
    layer: number;
    /** Face the camera (3D); false keeps quads in the XY plane for 2D scenes. */
    billboard: boolean;
    /** Particles keep their world position when the emitter moves; false moves them with it. */
    world_space: boolean;
    /** Extra seed for the emitter's random stream (the entity id seeds it too). */
    seed: number;
}

/** Axis-aligned bounding box in world space, computed by the engine from the mesh and WorldTransform. Read only. */
export interface Bounds {
    /** Minimum corner. */
    min: Vec3;
    /** Maximum corner. */
    max: Vec3;
}

/** Physics body. Dynamic bodies fall and collide; static bodies never move; kinematic bodies move by their Velocity and push dynamic ones. Uses the entity's Transform as world space (physics entities should be roots). */
export interface RigidBody {
    /** 0 dynamic, 1 static, 2 kinematic. */
    kind: number;
    /** Kilograms; ignored for static bodies. */
    mass: number;
    /** Bounciness 0..1. */
    restitution: number;
    /** Coulomb friction coefficient. */
    friction: number;
    /** Velocity lost per second (fraction). */
    linear_damping: number;
    /** Angular velocity lost per second (fraction). */
    angular_damping: number;
    /** Multiplier on world gravity. */
    gravity_scale: number;
    /** Set by the engine when the body came to rest; cleared when touched. */
    sleeping: boolean;
    /** Never rotate (characters on capsules stay upright). */
    lock_rotation: boolean;
    /** Continuous collision: each step the body is swept along its motion, relative to every shape it may touch (static, kinematic, and dynamic bodies moving too), and stops a skin short of the first impact, so thin walls hold and fast bodies do not cross each other at any speed. A sphere is cast exactly against the other shape; a box or capsule is swept by samples (docs/design/physics.md, Continuous collision). Bodies moving less than half their size per step are not swept. */
    ccd: boolean;
}

/** Connects this body to another body, to any entity as a fixed point, or to a point in the world: a distance joint keeps two anchors a rod's length apart (or a rope's, pulling only; with stiffness it is a spring), a ball joint pins them together while both rotate freely, a hinge pins them and allows rotation about one axis only, a slider lets the body move along one axis only, each with optional limits and a motor (docs/design/physics.md, Joints). Solved with the contacts every tick; when the force carried exceeds break_force the joint breaks (joint.broken event, component removed). */
export interface Joint {
    /** 0 distance (rod, or rope when rope is set, or spring when stiffness is set), 1 ball (anchors pinned together), 2 hinge (pinned, turning about axis only), 3 slider (prismatic: moving along axis only, no rotation relative to the target). */
    kind: number;
    /** Path or name of the other entity (a body, or any entity as an immovable point); empty pins to the world point target_anchor. */
    target: string;
    /** Attachment point on this body, in its local frame. */
    anchor: Vec3;
    /** Attachment point on the target in its local frame, or a world point when there is no target. */
    target_anchor: Vec3;
    /** Rest length of a distance joint; negative takes the anchors' distance at the first step and writes it here. */
    distance: number;
    /** Distance joints only: pull when the anchors are farther than distance, never push. */
    rope: boolean;
    /** Distance joints: newtons per meter of stretch; above 0 the rod is a spring (a bungee with rope) instead of a rigid length. */
    stiffness: number;
    /** Springs: newton-seconds per meter, the drag on the stretch speed. */
    damping: number;
    /** Force (newtons) above which the joint breaks; 0 never breaks. */
    break_force: number;
    /** Force the joint carried in the last step, written by the engine. */
    force: number;
    /** Hinge: the axis of rotation; slider: the axis of travel. In this body's local frame. */
    axis: Vec3;
    /** Hinge and slider: the axis in the target's frame; zero takes the body's axis at the first step and writes it here. */
    target_axis: Vec3;
    /** Hinge and slider: a direction across the axis in the target's frame from which the turn is measured; zero takes it at the first step and writes it here. */
    reference: Vec3;
    /** Hinge: keep angle between lower and upper (equal values lock the hinge). Slider: keep translation between them. */
    limit: boolean;
    /** Lower limit, when limit is set: radians for a hinge, meters along the axis for a slider. */
    lower: number;
    /** Upper limit, when limit is set: radians for a hinge, meters along the axis for a slider. */
    upper: number;
    /** The speed the motor drives the body to relative to the target: radians per second about a hinge's axis, meters per second along a slider's. */
    motor_speed: number;
    /** Hinge: the most torque the motor applies; 0 turns the motor off. */
    motor_torque: number;
    /** Slider: the most force the motor applies along the axis; 0 turns the motor off. */
    motor_force: number;
    /** Hinge: the body's rotation about the axis relative to the target, in radians, written by the engine every step. */
    angle: number;
    /** Slider: how far this body's anchor sits along the axis from the target's anchor, in meters, written by the engine every step. */
    translation: number;
    /** The body's speed relative to the target, written by the engine every step: radians per second about a hinge's axis, meters per second along a slider's. */
    speed: number;
    /** Whether this body and the joint's target body collide with each other; false lets a ragdoll's limbs or a chain's links overlap where the joint holds them. */
    collide_connected: boolean;
}

/** A 2D platformer body: an axis-aligned box in the XY plane that falls under gravity and is stopped by the solid tiles of a TileMap and by kinematic bodies (docs/design/tilemaps.md, 2D physics). Every tick the engine adds gravity, carries the body with the platform it rides, moves along X then Y, resolves against solid cells (one-way tiles only from above), walks slopes and steps, writes Transform.position and the contact flags, and emits body2d.landed. A kinematic body moves by its velocity alone and is a platform for the others. Scripts steer by writing velocity. */
export interface Body2D {
    /** Units per second, relative to what carries the body (a platform or a body it rides); scripts set x from input and y for a jump, the engine adds gravity and zeroes what a tile stops. */
    velocity: Vec2;
    /** Units per second squared along Y (negative is down). */
    gravity: number;
    /** Fastest downward speed. */
    max_fall: number;
    /** Half extents of the box. */
    size: Vec2;
    /** Box center relative to the entity's position. */
    offset: Vec2;
    /** Path or name of the TileMap entity to collide with; empty takes the first one. */
    map: string;
    /** Standing on a solid tile (written by the engine). */
    grounded: boolean;
    /** -1 touching a wall on the left, 1 on the right, 0 none (written by the engine). */
    on_wall: number;
    /** Head against a tile (written by the engine). */
    on_ceiling: boolean;
    /** Moves by its velocity only (no gravity, no tiles) and is a solid platform for the other bodies, which ride it while standing on it. */
    kinematic: boolean;
    /** Kinematic bodies: catch bodies from above only (a lift that rises through the floor). */
    one_way: boolean;
    /** The height a grounded body climbs over a solid edge without jumping, and drops without leaving the ground (stairs, the top and the foot of a slope). */
    step: number;
    /** The body this one stands on and moves with, a platform or another dynamic body; 0 when none (written by the engine). */
    riding: number;
    /** 1 standing on a floor rising to the right, -1 rising to the left, 0 flat or in the air (written by the engine). */
    on_slope: number;
    /** Weight against other dynamic bodies: two that overlap sideways each give way by the other's share of the mass and exchange their speeds into each other as a collision of the two masses, so a sliding crate takes the one it hits along and a heavy crate barely moves when a light body runs into it (docs/design/tilemaps.md, Bodies against bodies). */
    mass: number;
    /** Whether this body is pushed apart from, stands on and carries other dynamic bodies; false passes through them (ghosts, pickups with a body). */
    collide_bodies: boolean;
    /** Bounciness 0..1: the speed kept, reversed, when the body hits a floor, a ceiling, a wall, a platform or another body (a ball at 0.7 bounces to half its height; between two bodies the larger restitution counts, and momentum is kept); 0 stops dead. A landing slower than half a unit per second lands instead of bouncing, and body2d.bounced reports each bounce (docs/design/tilemaps.md, Friction and restitution). */
    restitution: number;
    /** Ground friction in units per second squared: how fast a grounded body's sideways speed (relative to what carries it) falls toward zero once nothing drives it, so a shoved crate slides to a stop; 0 slides forever. Applied after the move, so a script that writes velocity.x every tick is not slowed. */
    friction: number;
}

/** Collision shape centered on the entity (plus offset). Box half extents come from size; spheres use size.x as radius. Triggers report overlaps but do not push. */
export interface Collider {
    /** 0 box, 1 sphere, 2 capsule (a segment along local Y with round ends), 3 mesh (the triangles of a glTF asset, scaled by the Transform; for level geometry, mesh colliders do not collide with each other). */
    shape: number;
    /** Box half extents; radius in x for spheres; radius in x and half length of the straight part in y for capsules. */
    size: Vec3;
    /** Local offset of the shape center. */
    offset: Vec3;
    /** Overlap events only, no collision response. */
    is_trigger: boolean;
    /** For shape 3: the glTF file whose triangles collide (project-relative path); empty uses the entity's MeshRenderer mesh. */
    mesh: string;
    /** Bits of the layers this shape is on (bit 0 by default); [physics] layers in project.toml names them and physics.layers lists them. */
    layer: number;
    /** Bits of the layers this shape collides with (all by default). Two shapes collide, touch as a trigger, or answer a query only when each is on a layer the other's mask includes. */
    mask: number;
    /** Collision group: two shapes in the same negative group never collide, in the same positive group always collide, whatever their layers; 0 leaves it to the layers (docs/design/physics.md, Groups and exceptions). */
    group: number;
}

/** A sound attached to an entity: the engine starts it when autoplay is set (once, when the component appears or the scene loads) and keeps `playing` and `voice` current. Scripts use audio.play for one-shots. */
export interface AudioSource {
    /** Project-relative WAV path such as assets/hum.wav. */
    clip: string;
    /** Linear gain, 0..4. */
    volume: number;
    /** Playback rate multiplier. */
    pitch: number;
    /** Restart when the clip ends. */
    loop: boolean;
    /** Start playing as soon as the component exists. */
    autoplay: boolean;
    /** Whether a voice is currently playing this source (written by the engine). */
    playing: boolean;
    /** Id of the playing voice, 0 when silent (written by the engine). */
    voice: number;
}

/** A moving thing paths go around (docs/design/navigation.md, Obstacles): every tick, before the agents move, the engine blocks the navigation cells within radius (plus the grid's agent radius) of the entity's position, so nav.path, nav.reachable, nav.nearest and the agents route around it without a new bake. Carts, crates, doors. */
export interface NavObstacle {
    /** Radius of the blocked disc around the entity, in the grid's plane. */
    radius: number;
    /** false lifts the obstacle without removing the component. */
    enabled: boolean;
}

/** A thing that walks the navigation grid on its own (docs/design/navigation.md, Agents): every tick, after the scripts and the physics, the engine plans a path to its goal around the obstacles, heads for the next corner, picks the velocity that keeps it clear of the other agents and the obstacles, and moves the entity (Velocity.linear when it has a Velocity, else Transform.position). Scripts set mode, goal or target, speed and radius and read state; nav.arrived and nav.stuck are emitted on the transitions. */
export interface NavAgent {
    /** 0 idle (the engine leaves the entity alone), 1 walk to goal, 2 follow target. */
    mode: number;
    /** The point to reach in mode 1. */
    goal: Vec3;
    /** The entity to follow in mode 2. */
    target: number;
    /** Top speed, units per second. */
    speed: number;
    /** The agent's radius for keeping clear of other agents and obstacles. */
    radius: number;
    /** Distance from the goal at which the agent stops (state 2). */
    arrive: number;
    /** Ticks between path replans; a goal that moved by half a cell or a corner that got blocked replans at once. */
    replan: number;
    /** Weight of the local avoidance against the desired velocity; 0 walks the path regardless of the others. */
    avoidance: number;
    /** How much the agent prefers slowing down behind an agent ahead that goes its way (or stands) over passing it: 0 passes when it can, 1 keeps to a line; agents with the same goal then form a queue instead of a ring. Crossing and oncoming agents are still avoided by turning. */
    queue: number;
    /** Agents with a lower priority get out of this one's way: its avoidance ignores them while theirs avoids it. */
    priority: number;
    /** 0 idle, 1 moving, 2 arrived, 3 stuck: the goal cannot be reached or the target is gone (written by the engine). */
    state: number;
    /** The velocity chosen this tick (written by the engine). */
    velocity: Vec3;
    /** The point the agent is heading for: the next corner of its path, or the goal (written by the engine). */
    corner: Vec3;
    /** Length of the remaining path (written by the engine). */
    distance: number;
    /** Agents and obstacles the avoidance considered this tick (written by the engine). */
    neighbours: number;
    /** Whether the agent slowed down behind an agent ahead this tick (written by the engine). */
    queued: boolean;
}

/** Morph target weights set by script, over the ones the clip plays (docs/design/animation.md, Morph targets): every entry replaces the weight of its target for the entity's mesh asset; targets not listed keep the clip's or the file's default. animation.morph edits the list by name. */
export interface Morph {
    /** The targets and their weights. */
    weights: MorphWeight[];
}

export interface Components {
    Transform: Transform;
    WorldTransform: WorldTransform;
    Velocity: Velocity;
    Health: Health;
    Lifetime: Lifetime;
    Camera: Camera;
    Light: Light;
    MeshRenderer: MeshRenderer;
    Sprite: Sprite;
    SpriteAnimation: SpriteAnimation;
    TileMap: TileMap;
    Animator: Animator;
    IK: IK;
    LookAt: LookAt;
    ParticleEmitter: ParticleEmitter;
    Bounds: Bounds;
    RigidBody: RigidBody;
    Joint: Joint;
    Body2D: Body2D;
    Collider: Collider;
    AudioSource: AudioSource;
    NavObstacle: NavObstacle;
    NavAgent: NavAgent;
    Morph: Morph;
}

export type ComponentName = keyof Components;

export const componentNames: readonly ComponentName[] = ["Transform", "WorldTransform", "Velocity", "Health", "Lifetime", "Camera", "Light", "MeshRenderer", "Sprite", "SpriteAnimation", "TileMap", "Animator", "IK", "LookAt", "ParticleEmitter", "Bounds", "RigidBody", "Joint", "Body2D", "Collider", "AudioSource", "NavObstacle", "NavAgent", "Morph"];

